370	 * Validate API keys for configured multi-model providers.
371	 * Returns available and missing provider lists, and the voices not planned because their agy route's opt-in is off
372	 * (cycle-127 FR-1: neither valid nor missing — a voice that cannot exist on this host is never counted as a failed one).
373	 */
374	export function validateApiKeys(config: MultiModelConfig, gate: AgyGate, trusted?: TrustedConfig): {
375	  valid: Array<{ provider: string; modelId: string }>;
376	  missing: Array<{ provider: string; envVar: string }>;
377	  notPlanned: Array<{ provider: string; modelId: string; reason: "opt_in_required" }>;
378	} {
379	  const valid: Array<{ provider: string; modelId: string }> = [];
380	  const missing: Array<{ provider: string; envVar: string }> = [];
381	  const notPlanned: Array<{ provider: string; modelId: string; reason: "opt_in_required" }> = [];
382	
383	  for (const model of config.models) {
384	    // (r251-2 K7b: an unreadable config fails closed for EVERY google voice — its mode is unknown, so is its route: cheval,
385	    // reading the same file with PyYAML, might route it to agy and refuse; planned-as-HTTP would mis-count a failed voice)
386	    const gated = gate.readError !== undefined ? model.provider === "google" : isAgyRouted(model.provider, model.model_id, gate.mode);
387	    if (!gate.optIn && gated) {
388	      notPlanned.push({ provider: model.provider, modelId: model.model_id, reason: "opt_in_required" });
389	      continue;
390	    }
391	    // (cycle-129 D-7.5: a keyless or insecure declaration the PR head adds and the trusted config does not carry is refused
392	    // by name — before the key map, so a head that re-declares a built-in provider insecure is refused too)
393	    if (trusted?.headOnlyRefused.includes(model.provider)) {
394	      missing.push({ provider: model.provider, envVar: headOnlyRefusal(model.provider) });
395	      continue;
396	    }
397	    // (cycle-129 D-7.5: a provider the TRUSTED config declares keyless needs no env var; cheval authenticates it)
398	    if (trusted?.providers[model.provider]?.keyless === true) {
399	      valid.push({ provider: model.provider, modelId: model.model_id });
400	      continue;
401	    }
402	    const envVar = providerKeyEnv(model.provider, trusted);
403	    if (!envVar) {
404	      missing.push({
405	        provider: model.provider,
406	        envVar: trusted?.providers[model.provider] !== undefined
407	          ? `provider ${model.provider} declares no credential (set keyless: true or auth: "{env:VAR}")`
408	          : `Unknown provider: ${model.provider}`,
409	      });
410	      continue;
411	    }
412	    // (a `*-headless` entry is a cheval CLI hop that authenticates itself — every voice dispatches through cheval — so
413	    // it needs no key; the gate dropped the keyless host's claude-headless entry: cycle-126 thirty-seventh run, e2b DISS-C-003)
414	    if (isHeadlessModelId(model.model_id, model.provider) || process.env[envVar]) {
415	      valid.push({ provider: model.provider, modelId: model.model_id });
416	    } else {
417	      missing.push({ provider: model.provider, envVar });
418	    }
419	  }
420	
421	  return { valid, missing, notPlanned };
422	}
