442	 */
443	export function providerKeyEnv(provider: string, trusted?: TrustedConfig): string | undefined {
444	  if (Object.hasOwn(PROVIDER_API_KEY_ENV, provider)) return PROVIDER_API_KEY_ENV[provider];
445	  return trusted?.providers[provider]?.authEnv;
446	}
