        return None
    s = host.lower()
    try:
        if s.startswith("0x"):
            n = int(s, 16)
        elif s.startswith("0") and len(s) > 1 and s[1].isdigit():
            n = int(s, 8)
        elif s.isdigit():
            n = int(s, 10)
        else:
            return None
    except ValueError:
        return None
    if n < 0 or n > 0xFFFFFFFF:
        return None
    try:
        return str(ipaddress.IPv4Address(n))
    except (ValueError, ipaddress.AddressValueError):
        return None


